A measure $
u$ on $ X$ is said to be \emph{$\alpha$-homogeneous} for some $\alpha\in R \setminus \{0\}$ if  egin{equation} 
u(sB)=s^{-\alpha}
u(B),\qquad B\in\salg,\; s>0. \end{equation}

Suppose that Assumption~ef{assumption:U} holds. The following are equivalent for a measure $
u$ on $( X, \salg)$.  egin{itemize} \item[i)] The measure $
u$ is a nontrivial $\alpha$-homogeneous measure with  egin{equation} 
u(U_k)<\infty,\qquad k\in N\,. \end{equation} \item[ii)] The measure $
u$ is the push-forward of the measure $\pi\otimes	heta_\alpha$ by the map $(x,t)\mapsto tx$, where $\pi$ is a probability measure on $ X$ such that  egin{equation} \int_0^\infty \pi(tU_k)t^{\alpha-1} \, dt < \infty,\qquad k\in N, \end{equation} and $	heta_\alpha$ is the measure on $ R_{++}$ given by $	heta_\alpha(dt) := \alpha t^{-(\alpha+1)} \, dt$. \item[(iii)] For a probability measure $\pi$ on $ X$ such that \eqref{eq:pi-Sk} holds,  egin{equation} 
u(B) = \alpha \int_0^\infty \pi(t B) \, t^{\alpha-1} \, dt \end{equation} for all $B \in \salg$. \end{itemize}

Suppose that Assumption~ef{assumption:X} holds. Let $\cH$ be a countable family of measurable functions $h: X\mapsto R_+$ such that for all $h \in \cH$ and $x \in  X$ the function $ t \mapsto h(tx)$ is right-continuous (or left-continuous) on $ R_{++}$. A $\sigma$-finite measure $
u$ on $ X$ is $\alpha$-homogeneous and satisfies  egin{equation} \int_ X h(x) \, 
u(dx) <\infty,\qquad h\in\cH, \end{equation} and  egin{equation} 
u\left( igcap_{h\in\cH} \{x\in X:\; h(x)=0\}ight)=0 \end{equation} if and only if there exists a probability measure $\pi$ on $ X$ such that \eqref{Eq:nu-rep} holds,  egin{equation} \int_{ X}\int_0^\infty h(tx) t^{-(\alpha+1)} \, dt \, \pi(dx) <\infty, \qquad h\in\cH, \end{equation} and  egin{displaymath} \pi\left((0,\infty)  igcap_{h \in \cH} \{x\in X:\; h(x)=0\}ight)=0. \end{displaymath}

conclusions:
A $\sigma$-finite measure $
u$ on $ X$ is $\alpha$-homogeneous and satisfies  egin{equation} \int_ X h(x) \, 
u(dx) <\infty,\qquad h\in\cH, \end{equation} and  egin{equation} 
u\left( igcap_{h\in\cH} \{x\in X:\; h(x)=0\}ight)=0 \end{equation} if and only if there exists a probability measure $\pi$ on $ X$ such that \eqref{Eq:nu-rep} holds,  egin{equation} \int_{ X}\int_0^\infty h(tx) t^{-(\alpha+1)} \, dt \, \pi(dx) <\infty, \qquad h\in\cH, \end{equation} and  egin{displaymath} \pi\left((0,\infty)  igcap_{h \in \cH} \{x\in X:\; h(x)=0\}ight)=0. \end{displaymath}

